head.script:
//
  (function(){
    try {
      var theme = localStorage.getItem('mpsc_theme');
      var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
      if (theme === 'dark' || (!theme && prefersDark)) {
        document.documentElement.setAttribute('data-theme', 'dark');
      } else {
        document.documentElement.setAttribute('data-theme', 'light');
      }

    } catch(e){}
  })();
//

head.b:skin:
/*
<Variable name="keycolor" description="Primary Accent Color" type="color" default="#1e40af" value="#1e40af"/>
<Variable name="primaryHover" description="Primary Hover Color" type="color" default="#1d4ed8" value="#1d4ed8"/>
<Variable name="accentColor" description="Secondary Accent Color" type="color" default="#d97706" value="#d97706"/>
<Variable name="bodyBg" description="Body Background Color" type="color" default="#f8fafc" value="#f8fafc"/>
<Variable name="cardBg" description="Card Background Color" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="textColor" description="Main Text Color" type="color" default="#0f172a" value="#0f172a"/>
<Variable name="mutedColor" description="Muted Text Color" type="color" default="#64748b" value="#64748b"/>
<Variable name="borderColor" description="Border Color" type="color" default="#e2e8f0" value="#e2e8f0"/>
<Variable name="bodyFont" description="Body Font" type="font" default="400 16px 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" value="400 16px 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"/>
<Variable name="headingFont" description="Heading Font" type="font" default="700 24px 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" value="700 24px 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"/>
<Variable name="containerWidth" description="Site Max Container Width" type="length" default="1200px" value="1200px"/>
<Variable name="sidebarWidth" description="Sidebar Width" type="length" default="340px" value="340px"/>
*/

/* ==========================================================================
   CSS CUSTOM PROPERTIES (LIGHT & DARK THEMES)
   ========================================================================== */
:root {
  --primary: $(keycolor);
  --primary-hover: $(primaryHover);
  --primary-light: #eff6ff;
  --accent: $(accentColor);
  --accent-light: #fef3c7;
  --bg-page: $(bodyBg);
  --bg-surface: $(cardBg);
  --bg-subtle: #f1f5f9;
  --text-main: $(textColor);
  --text-secondary: #334155;
  --text-muted: $(mutedColor);
  --border-color: $(borderColor);
  --border-subtle: #f1f5f9;
  --border-focus: #3b82f6;
  --font-base: $(bodyFont);
  --font-heading: $(headingFont);
  --container-max: $(containerWidth);
  --sidebar-w: $(sidebarWidth);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
  --line-height-body: 1.65;
  --line-height-article: 1.8;
}

[data-theme='dark'] {
  --primary: #3b82f6;
  --primary-hover: #60a5fa;
  --primary-light: rgba(59, 130, 246, 0.15);
  --accent: #fbbf24;
  --accent-light: rgba(251, 191, 36, 0.15);
  --bg-page: #0b0f19;
  --bg-surface: #131b2e;
  --bg-subtle: #1e293b;
  --text-main: #f8fafc;
  --text-secondary: #cbd5e1;
  --text-muted: #94a3b8;
  --border-color: #27354f;
  --border-subtle: #1e293b;
  --border-focus: #60a5fa;
  --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.5);
  --shadow-sm: 0 2px 4px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 8px -1px rgba(0, 0, 0, 0.45);
  --shadow-lg: 0 10px 20px -3px rgba(0, 0, 0, 0.5);
}

/* ==========================================================================
   CSS RESET & BASE STYLES
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-base);
  font-size: 1rem;
  line-height: var(--line-height-body);
  color: var(--text-main);
  background-color: var(--bg-page);
  transition: background-color var(--transition-normal), color var(--transition-normal);
  overflow-x: hidden;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--primary-hover);
}

img, svg, picture {
  max-width: 100%;
  height: auto;
  display: block;
}

button, input, textarea, select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

table {
  border-collapse: collapse;
  width: 100%;
}

/* Accessibility: Skip Link & Focus */
.skip-to-content {
  position: absolute;
  top: -999px;
  left: 1rem;
  background: var(--primary);
  color: #ffffff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  z-index: 99999;
  font-weight: 600;
  transition: top var(--transition-fast);
}

.skip-to-content:focus {
  top: 1rem;
}

:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* Container */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
}

/* ==========================================================================
   TOP ANNOUNCEMENT & UTILITY BAR
   ========================================================================== */
.top-bar {
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  font-size: 0.8125rem;
  padding: 0.375rem 0;
  transition: background-color var(--transition-normal);
}

.top-bar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.top-ticker {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  overflow: hidden;
  white-space: nowrap;
}

.ticker-badge {
  background-color: var(--primary);
  color: #ffffff;
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 0.125rem 0.5rem;
  border-radius: var(--radius-full);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  flex-shrink: 0;
}

.ticker-text {
  color: var(--text-secondary);
  text-overflow: ellipsis;
  overflow: hidden;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
}



.theme-toggle-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  background-color: var(--bg-subtle);
  color: var(--text-main);
  transition: all var(--transition-fast);
}

.theme-toggle-btn:hover {
  background-color: var(--primary-light);
  color: var(--primary);
}

.theme-icon-sun { display: none; }
.theme-icon-moon { display: block; }

[data-theme='dark'] .theme-icon-sun { display: block; }
[data-theme='dark'] .theme-icon-moon { display: none; }

/* ==========================================================================
   SITE HEADER & BRANDING
   ========================================================================== */
.site-header {
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  padding: 1.25rem 0;
  transition: background-color var(--transition-normal);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.header-brand {
  flex-shrink: 0;
}

.site-title {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 800;
  line-height: 1.2;
  margin: 0;
}

.site-title a {
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.site-title .title-accent {
  color: var(--accent);
}

.site-description {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
  max-width: 420px;
}

.header-logo-img {
  max-height: 52px;
  width: auto;
}

/* Header Ad Container (Responsive 728x90) */
.header-ad-wrap {
  flex-grow: 1;
  display: flex;
  justify-content: flex-end;
  min-height: 90px;
}

.mobile-nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  background-color: var(--bg-subtle);
  color: var(--text-main);
}

/* ==========================================================================
   NAVIGATION BAR
   ========================================================================== */
.main-navbar {
  background-color: var(--primary);
  color: #ffffff;
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: var(--shadow-sm);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.nav-links {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.25rem;
}

.nav-item a {
  display: inline-block;
  color: #e2e8f0;
  font-weight: 600;
  font-size: 0.875rem;
  padding: 0.75rem 0.875rem;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.nav-item a:hover, .nav-item.current-page a {
  color: #ffffff;
  background-color: rgba(255, 255, 255, 0.12);
}

.nav-search-box {
  position: relative;
  max-width: 240px;
}

.nav-search-input {
  background-color: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: #ffffff;
  padding: 0.5rem 2.75rem 0.5rem 0.875rem;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  width: 100%;
  min-height: 40px;
  transition: all var(--transition-fast);
}

.nav-search-input::placeholder {
  color: rgba(255, 255, 255, 0.75);
}

.nav-search-input:focus {
  background-color: #ffffff;
  color: #0f172a;
  outline: none;
  box-shadow: 0 0 0 2px var(--accent);
}

.nav-search-btn {
  position: absolute;
  right: 0.25rem;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255, 255, 255, 0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 40px;
  min-height: 40px;
  padding: 0.5rem;
}

.nav-search-input:focus ~ .nav-search-btn {
  color: #0f172a;
}

/* ==========================================================================
   AD CONTAINERS (ADSENSE COMPLIANT)
   ========================================================================== */
.ad-slot-section {
  padding: 1rem 0;
  display: flex;
  justify-content: center;
}

.ad-container {
  width: 100%;
  text-align: center;
  position: relative;
  background-color: var(--bg-surface);
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.75rem;
  min-height: 90px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.ad-label {
  font-size: 0.625rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.375rem;
}

.ad-placeholder {
  color: var(--text-muted);
  font-size: 0.8125rem;
  font-style: italic;
}

/* ==========================================================================
   MAIN CONTENT LAYOUT (2-COLUMN GRID)
   ========================================================================== */
.site-content {
  padding-top: 1.5rem;
  padding-bottom: 2.5rem;
  flex-grow: 1;
}

.layout-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--sidebar-w);
  gap: 2rem;
  align-items: start;
}

.primary-col {
  min-width: 0;
}

.secondary-col {
  min-width: 0;
}

/* ==========================================================================
   FEATURED / HERO POST (STUDY SPOTLIGHT)
   ========================================================================== */
.featured-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  margin-bottom: 2rem;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.featured-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--primary);
}

.featured-inner {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  align-items: center;
}

.featured-media {
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background-color: var(--bg-subtle);
}

.featured-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.featured-card:hover .featured-img {
  transform: scale(1.03);
}

.featured-content {
  padding: 1.5rem;
}

.featured-tag {
  display: inline-block;
  background-color: var(--accent-light);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-full);
  margin-bottom: 0.75rem;
}

.featured-title {
  font-family: var(--font-heading);
  font-size: 1.35rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 0.75rem;
}

.featured-title a {
  color: var(--text-main);
}

.featured-title a:hover {
  color: var(--primary);
}

.featured-snippet {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.55;
  margin-bottom: 1rem;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ==========================================================================
   POST ARCHIVE / LIST VIEW (CARDS GRID)
   ========================================================================== */
.archive-header-banner {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-left: 4px solid var(--primary);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  margin-bottom: 1.5rem;
}

.archive-header-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.archive-header-desc {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.posts-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.5rem;
}

.post-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-xs);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.post-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--primary);
}

.post-card-thumb-wrap {
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background-color: var(--bg-subtle);
  display: block;
}

.post-card-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.post-card:hover .post-card-thumb {
  transform: scale(1.04);
}

.post-thumb-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  color: var(--primary);
  background: linear-gradient(135deg, var(--bg-subtle) 0%, var(--primary-light) 100%);
}

.post-card-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  background-color: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(4px);
  color: #ffffff;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-sm);
  z-index: 2;
}

.post-card-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.post-card-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-bottom: 0.5rem;
}

.post-card-meta span {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.post-card-title {
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 0.625rem;
}

.post-card-title a {
  color: var(--text-main);
}

.post-card-title a:hover {
  color: var(--primary);
}

.post-card-snippet {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
  margin-bottom: 1rem;
  flex-grow: 1;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-subtle);
  font-size: 0.75rem;
}

.read-more-link {
  font-weight: 700;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.read-more-link:hover {
  gap: 0.5rem;
}

/* ==========================================================================
   PAGINATION NAVIGATION
   ========================================================================== */
.pagination-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: 2rem;
  padding: 1rem 0;
}

.pagination-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);
  box-shadow: var(--shadow-xs);
  transition: all var(--transition-fast);
}

.pagination-btn:hover:not(.disabled) {
  background-color: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.pagination-btn.disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.pagination-btn.home-btn {
  padding: 0.625rem 1rem;
}

/* ==========================================================================
   SINGLE POST / ARTICLE VIEW
   ========================================================================== */
.article-wrapper {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-xs);
}

.breadcrumb-nav {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}

.breadcrumb-list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.375rem;
}

.breadcrumb-item a {
  color: var(--text-muted);
}

.breadcrumb-item a:hover {
  color: var(--primary);
}

.breadcrumb-separator {
  color: var(--border-color);
}

.article-header {
  margin-bottom: 1.5rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--border-color);
}

.article-title {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 800;
  line-height: 1.3;
  color: var(--text-main);
  margin-bottom: 1rem;
}

.article-meta-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.article-meta-left {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.article-author-info {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.author-avatar-img {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
}

.author-name-text {
  font-weight: 600;
  color: var(--text-main);
}

.article-meta-item {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.exam-update-pill {
  background-color: var(--primary-light);
  color: var(--primary);
  font-weight: 700;
  padding: 0.125rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
}

/* Table of Contents (TOC) */
.toc-box {
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-left: 4px solid var(--accent);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  margin: 1.5rem 0 2rem 0;
}

.toc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.toc-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.toc-toggle-btn {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--primary);
  background-color: var(--bg-surface);
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.toc-nav {
  margin-top: 1rem;
  padding-top: 0.75rem;
  border-top: 1px dashed var(--border-color);
}

.toc-list {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.toc-item a {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.4;
  display: inline-block;
}

.toc-item a:hover {
  color: var(--primary);
  text-decoration: underline;
}

.toc-sub {
  margin-left: 1.25rem;
}

/* Article Body Typography */
.article-body {
  font-size: 1.0625rem;
  line-height: var(--line-height-article);
  color: var(--text-secondary);
  word-wrap: break-word;
}

.article-body p {
  margin-bottom: 1.25rem;
}

.article-body h2 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-main);
  margin-top: 2rem;
  margin-bottom: 1rem;
  padding-bottom: 0.375rem;
  border-bottom: 2px solid var(--border-subtle);
}

.article-body h3 {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  margin-top: 1.75rem;
  margin-bottom: 0.75rem;
}

.article-body h4 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
  margin-top: 1.5rem;
  margin-bottom: 0.5rem;
}

.article-body ul, .article-body ol {
  margin-bottom: 1.25rem;
  padding-left: 1.5rem;
}

.article-body ul { list-style: disc; }
.article-body ol { list-style: decimal; }

.article-body li {
  margin-bottom: 0.375rem;
}

.article-body blockquote {
  border-left: 4px solid var(--primary);
  background-color: var(--bg-subtle);
  padding: 1rem 1.25rem;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  font-style: italic;
  color: var(--text-main);
  margin: 1.5rem 0;
}

.article-body pre {
  background-color: #0f172a;
  color: #f8fafc;
  padding: 1rem;
  border-radius: var(--radius-md);
  overflow-x: auto;
  font-size: 0.875rem;
  margin: 1.5rem 0;
  position: relative;
}

.article-body code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.875em;
  background-color: var(--bg-subtle);
  color: var(--primary);
  padding: 0.125rem 0.375rem;
  border-radius: 4px;
}

.article-body pre code {
  background-color: transparent;
  color: inherit;
  padding: 0;
}

/* Responsive Tables (Cut-offs, Marks, Exam Pattern) */
.table-responsive-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  margin: 1.5rem 0;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
}

.article-body table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.article-body th {
  background-color: var(--primary);
  color: #ffffff;
  font-weight: 700;
  text-align: left;
  padding: 0.75rem 1rem;
}

.article-body td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-secondary);
}

.article-body tr:nth-child(even) {
  background-color: var(--bg-subtle);
}

.article-body tr:hover {
  background-color: var(--primary-light);
}

/* Callout Alert Boxes (Educational Notes) */
.callout {
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  margin: 1.5rem 0;
  border-left: 4px solid;
  display: flex;
  gap: 0.75rem;
}

.callout-info {
  background-color: var(--primary-light);
  border-color: var(--primary);
  color: var(--text-main);
}

.callout-warning {
  background-color: var(--accent-light);
  border-color: var(--accent);
  color: #78350f;
}

.callout-success {
  background-color: #ecfdf5;
  border-color: #047857;
  color: #064e3b;
}

/* Exam PYQ Question Block Helper */
.qa-item {
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  margin: 1.5rem 0;
  box-shadow: var(--shadow-sm);
  transition: border-color var(--transition-fast);
}

.qa-item:hover {
  border-color: var(--border-hover);
}

.qa-question {
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-main);
  margin-bottom: 0.75rem;
  line-height: 1.6;
}

.qa-options {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.625rem;
  margin-bottom: 1rem;
}

.qa-option {
  background-color: var(--bg-surface);
  border: 1.5px solid var(--border-color);
  padding: 0.625rem 0.875rem;
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  user-select: none;
}

.qa-option:hover {
  border-color: var(--primary);
  background-color: var(--primary-light);
}

.qa-option.opt-correct {
  background-color: #ecfdf5 !important;
  border-color: #059669 !important;
  color: #065f46 !important;
  font-weight: 600;
}

.qa-option.opt-correct::after {
  content: " ✓ योग्य";
  margin-left: auto;
  color: #059669;
  font-weight: 700;
  font-size: 0.8125rem;
}

.qa-option.opt-incorrect {
  background-color: #fef2f2 !important;
  border-color: #dc2626 !important;
  color: #991b1b !important;
}

.qa-option.opt-incorrect::after {
  content: " ✗ अयोग्य";
  margin-left: auto;
  color: #dc2626;
  font-weight: 700;
  font-size: 0.8125rem;
}

/* Button & Native Details Accordion Support */
.qa-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--primary);
  background-color: var(--bg-surface);
  border: 1px solid var(--primary);
  padding: 0.375rem 0.75rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  user-select: none;
}

.qa-toggle-btn:hover {
  background-color: var(--primary);
  color: #ffffff;
}

details.qa-explanation-box {
  margin-top: 0.85rem;
  border: none;
}

details.qa-explanation-box summary.qa-toggle-btn {
  list-style: none;
}

details.qa-explanation-box summary.qa-toggle-btn::-webkit-details-marker {
  display: none;
}

details.qa-explanation-box[open] summary.qa-toggle-btn {
  background-color: var(--primary-light);
  border-color: var(--primary);
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.qa-answer {
  display: none;
  margin-top: 0.75rem;
  padding: 0.875rem 1rem;
  background-color: #ecfdf5;
  border-left: 4px solid #059669;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  color: #064e3b;
  line-height: 1.6;
}

.qa-answer.is-visible,
details.qa-explanation-box[open] .qa-answer,
details.qa-explanation-box .qa-answer {
  display: block;
}

[data-theme='dark'] .qa-answer {
  background-color: rgba(6, 78, 59, 0.25);
  border-left-color: #10b981;
  color: #a7f3d0;
}

[data-theme='dark'] .qa-option.opt-correct {
  background-color: rgba(5, 150, 105, 0.2) !important;
  border-color: #10b981 !important;
  color: #a7f3d0 !important;
}

[data-theme='dark'] .qa-option.opt-incorrect {
  background-color: rgba(220, 38, 38, 0.2) !important;
  border-color: #f87171 !important;
  color: #fca5a5 !important;
}

/* PDF Download Button */
.btn-download-pdf {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 0.9375rem;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: 0 4px 6px -1px rgba(220, 38, 38, 0.3);
  transition: all var(--transition-fast);
  margin: 1rem 0;
}

.btn-download-pdf:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 12px -2px rgba(220, 38, 38, 0.4);
}

/* Post Tags Cloud */
.article-tags-wrap {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 2rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--border-color);
}

.article-tags-label {
  font-weight: 700;
  font-size: 0.8125rem;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.tag-pill {
  background-color: var(--bg-subtle);
  color: var(--text-secondary);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
  transition: all var(--transition-fast);
}

.tag-pill:hover {
  background-color: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

/* Social Share Bar */
.share-bar-wrap {
  margin-top: 1.5rem;
  padding: 1.25rem;
  background-color: var(--bg-subtle);
  border-radius: var(--radius-md);
}

.share-bar-title {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #334155;
  margin-bottom: 0.75rem;
}
[data-theme='dark'] .share-bar-title { color: #94a3b8; }

.share-buttons-grid {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.share-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: #ffffff;
  padding: 0.375rem 0.75rem;
  border-radius: var(--radius-sm);
  transition: transform var(--transition-fast);
}

.share-btn:hover {
  transform: translateY(-1px);
}

.share-btn.whatsapp { background-color: #128c7e; }
.share-btn.telegram { background-color: #006da8; }
.share-btn.twitter { background-color: #0f1419; }
.share-btn.facebook { background-color: #1877f2; }
.share-btn.linkedin { background-color: #0a66c2; }
.share-btn.copy-link { background-color: #475569; }
.share-btn.print-page { background-color: #0369a1; }

/* Author Bio Card */
.author-bio-card {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  margin-top: 2rem;
}

.author-bio-avatar {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-full);
  flex-shrink: 0;
  object-fit: cover;
}

.author-bio-name {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.25rem;
}

.author-bio-desc {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.45;
}

/* Post Navigation (Prev / Next) */
.post-nav-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
}

.post-nav-card {
  display: flex;
  flex-direction: column;
  padding: 1rem;
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.post-nav-card:hover {
  border-color: var(--primary);
  transform: translateY(-2px);
}

.post-nav-card.next {
  text-align: right;
}

.post-nav-label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
}

.post-nav-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Related Posts Section */
.related-posts-section {
  margin-top: 2.5rem;
  padding-top: 1.5rem;
  border-top: 2px solid var(--border-subtle);
}

.section-title-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.25rem;
}

.section-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.section-title::before {
  content: '';
  width: 4px;
  height: 1.25rem;
  background-color: var(--primary);
  border-radius: 2px;
}

.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.related-card {
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition-fast);
}

.related-card:hover {
  border-color: var(--primary);
  transform: translateY(-2px);
}

.related-thumb-wrap {
  aspect-ratio: 16 / 9;
  overflow: hidden;
}

.related-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.related-body {
  padding: 0.75rem;
}

.related-title {
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--text-main);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ==========================================================================
   BLOGGER NATIVE COMMENTS SECTION
   ========================================================================== */
.comments-section {
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
}

.comments-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.comment-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 2rem;
}

.comment-item {
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem;
}

.comment-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.5rem;
  font-size: 0.8125rem;
}

.comment-author-name {
  font-weight: 700;
  color: var(--text-main);
}

.comment-timestamp {
  color: var(--text-muted);
}

.comment-body {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.comment-form-wrap {
  margin-top: 1.5rem;
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.25rem;
}

.comment-form-wrap iframe {
  border: none;
  width: 100%;
  min-height: 220px;
}

/* ==========================================================================
   SIDEBAR WIDGETS
   ========================================================================== */
.sidebar-sticky {
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

.widget-box {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  box-shadow: var(--shadow-xs);
}

.widget-title {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
  padding-bottom: 0.625rem;
  margin-bottom: 1rem;
  border-bottom: 2px solid var(--primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.widget-title-icon {
  color: var(--primary);
}

/* Search Widget */
.search-input-group {
  display: flex;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  background-color: var(--bg-subtle);
}

.search-field {
  width: 100%;
  border: none;
  background: transparent;
  padding: 0.625rem 0.875rem;
  font-size: 0.875rem;
  color: var(--text-main);
}

.search-field:focus {
  outline: none;
}

.search-btn {
  background-color: var(--primary);
  color: #ffffff;
  padding: 0 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color var(--transition-fast);
}

.search-btn:hover {
  background-color: var(--primary-hover);
}

/* Popular Posts Widget */
.popular-list {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
}

.popular-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.popular-rank {
  width: 26px;
  height: 26px;
  background-color: var(--primary-light);
  color: var(--primary);
  font-weight: 800;
  font-size: 0.75rem;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.popular-thumb-wrap {
  width: 60px;
  height: 60px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  flex-shrink: 0;
  background-color: var(--bg-subtle);
}

.popular-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.popular-info {
  flex-grow: 1;
  min-width: 0;
}

.popular-post-title {
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--text-main);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.popular-post-title:hover {
  color: var(--primary);
}

.popular-date {
  font-size: 0.6875rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
  display: block;
}

/* Labels / Categories Widget */
.label-list {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.label-list-item a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem 0.625rem;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  background-color: var(--bg-subtle);
  transition: all var(--transition-fast);
}

.label-list-item a:hover {
  background-color: var(--primary);
  color: #ffffff;
  padding-left: 0.875rem;
}

.label-count-badge {
  font-size: 0.6875rem;
  font-weight: 700;
  background-color: var(--bg-surface);
  color: var(--primary);
  padding: 0.125rem 0.375rem;
  border-radius: var(--radius-full);
}

.label-list-item a:hover .label-count-badge {
  background-color: rgba(255, 255, 255, 0.25);
  color: #ffffff;
}

/* Archive Widget */
.archive-list {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.archive-item a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.375rem 0;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  border-bottom: 1px dashed var(--border-subtle);
}

.archive-item a:hover {
  color: var(--primary);
}

/* Telegram Study Channel Promotion Box */
.telegram-banner-box {
  background: linear-gradient(135deg, #006da8 0%, #004d73 100%);
  color: #ffffff;
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  text-align: center;
  box-shadow: var(--shadow-sm);
}

.telegram-banner-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.375rem;
}

.telegram-banner-desc {
  font-size: 0.8125rem;
  opacity: 0.9;
  margin-bottom: 1rem;
}

.telegram-banner-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background-color: #ffffff;
  color: #005b8e !important;
  font-weight: 700;
  font-size: 0.875rem;
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-fast);
}

.telegram-banner-btn:hover {
  transform: translateY(-2px);
}

/* ==========================================================================
   FOOTER SECTION
   ========================================================================== */
.site-footer {
  background-color: #0b1120;
  color: #94a3b8;
  padding-top: 3rem;
  border-top: 1px solid #1e293b;
  margin-top: auto;
}

.footer-columns-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 2rem;
  padding-bottom: 2.5rem;
}

.footer-col-title {
  color: #f8fafc;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.footer-about-text {
  font-size: 0.8125rem;
  line-height: 1.6;
  margin-bottom: 1.25rem;
}

.footer-links-list {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.footer-link-item a {
  color: #94a3b8;
  font-size: 0.8125rem;
  transition: color var(--transition-fast);
}

.footer-link-item a:hover {
  color: #ffffff;
  padding-left: 0.25rem;
}

.footer-bottom-bar {
  border-top: 1px solid #1e293b;
  padding: 1.25rem 0;
  font-size: 0.8125rem;
}

.footer-bottom-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.copyright-text {
  color: #94a3b8;
}

.footer-legal-links {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.footer-legal-links a {
  color: #94a3b8;
}

.footer-legal-links a:hover {
  color: #cbd5e1;
}

/* ==========================================================================
   MOBILE DRAWER NAVIGATION
   ========================================================================== */
.drawer-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  z-index: 9998;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-normal);
}

.drawer-backdrop.is-open {
  opacity: 1;
  visibility: visible;
}

.mobile-drawer {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 290px;
  max-width: 85vw;
  background-color: var(--bg-surface);
  z-index: 9999;
  transform: translateX(-100%);
  transition: transform var(--transition-normal);
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-lg);
}

.mobile-drawer.is-open {
  transform: translateX(0);
}

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem;
  border-bottom: 1px solid var(--border-color);
}

.drawer-title {
  font-weight: 700;
  color: var(--primary);
  font-size: 1.125rem;
}

.drawer-close-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  background-color: var(--bg-subtle);
  color: var(--text-main);
}

.drawer-body {
  padding: 1.25rem;
  overflow-y: auto;
  flex-grow: 1;
}

.drawer-nav-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.drawer-nav-item a {
  display: block;
  padding: 0.625rem 0.75rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--text-main);
  background-color: var(--bg-subtle);
}

.drawer-nav-item a:hover {
  background-color: var(--primary);
  color: #ffffff;
}

/* Back to Top Floating Button */
.back-to-top-btn {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  width: 44px;
  height: 44px;
  background-color: var(--primary);
  color: #ffffff;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
  z-index: 900;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all var(--transition-normal);
}

.back-to-top-btn.is-active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.back-to-top-btn:hover {
  background-color: var(--primary-hover);
  transform: translateY(-2px);
}

/* Reading Progress Bar */
.reading-progress-bar {
  position: fixed;
  top: 0;
  left: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--primary) 0%, var(--accent) 100%);
  width: 0%;
  z-index: 99999;
  transition: width 0.1s ease-out;
}

/* Toast Notification (Copy Link Feedback) */
.toast-msg {
  position: fixed;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background-color: #0f172a;
  color: #ffffff;
  padding: 0.625rem 1.25rem;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 600;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-fast);
  z-index: 99999;
}

.toast-msg.show {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

/* ==========================================================================
   RESPONSIVE MEDIA QUERIES (MOBILE-FIRST BREAKPOINTS)
   ========================================================================== */
@media (max-width: 1024px) {
  .layout-grid {
    grid-template-columns: minmax(0, 1fr) 300px;
    gap: 1.5rem;
  }
  .featured-inner {
    grid-template-columns: 1fr;
  }
  .footer-columns-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 860px) {
  .layout-grid {
    grid-template-columns: 1fr;
  }
  .secondary-col {
    margin-top: 2rem;
  }
  .header-ad-wrap {
    display: none;
  }
  .mobile-nav-toggle {
    display: flex;
  }
  .main-navbar {
    display: none;
  }
  .posts-grid {
    grid-template-columns: 1fr;
  }
  .article-title {
    font-size: 1.5rem;
  }
  .article-wrapper {
    padding: 1.25rem;
  }
  .related-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 600px) {
  .top-ticker {
    display: none;
  }
  .post-nav-grid {
    grid-template-columns: 1fr;
  }
  .footer-columns-grid {
    grid-template-columns: 1fr;
  }
  .author-bio-card {
    flex-direction: column;
    text-align: center;
  }
  .qa-options {
    grid-template-columns: 1fr;
  }
}

