/* ==========================================================================
   PRINT STYLES (@media print)
   ========================================================================== */
@media print {
  .top-bar, .main-navbar, .ad-slot-section, .secondary-col,
  .site-footer, .share-bar-wrap, .post-nav-grid, .related-posts-section,
  .comments-section, .back-to-top-btn, .reading-progress-bar, .mobile-nav-toggle {
    display: none !important;
  }
  body, .article-wrapper {
    background: #ffffff !important;
    color: #000000 !important;
    padding: 0 !important;
    border: none !important;
    box-shadow: none !important;
  }
  .layout-grid {
    display: block !important;
  }
  .article-title {
    font-size: 20pt;
  }
  a {
    color: #000000 !important;
    text-decoration: underline;
  }
}

head.b:template-skin:
body#layout {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: #f1f5f9;
}
body#layout .header-inner, body#layout .layout-grid {
  display: block;
}
body#layout .section {
  border: 1px dashed #94a3b8;
  margin: 10px 0;
  padding: 8px;
  background: #ffffff;
  border-radius: 6px;
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  'use strict';

  /* 1. Dynamic Year in Footer */
  var yearEl = document.getElementById('footerCurrentYear');
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }

  /* 2. Dark / Light Theme Toggle */
  var themeToggleBtn = document.getElementById('themeToggleBtn');
  if (themeToggleBtn) {
    themeToggleBtn.addEventListener('click', function() {
      var current = document.documentElement.getAttribute('data-theme') || 'light';
      var next = (current === 'dark') ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', next);
      try { localStorage.setItem('mpsc_theme', next); } catch(e){}
    });
  }

  /* 3. Mobile Navigation Drawer */
  var mobileToggle = document.getElementById('mobileNavToggle');
  var drawer = document.getElementById('mobileDrawer');
  var backdrop = document.getElementById('drawerBackdrop');
  var closeBtn = document.getElementById('drawerCloseBtn');

  function openDrawer() {
    if (drawer && backdrop) {
      drawer.classList.add('is-open');
      backdrop.classList.add('is-open');
      if (mobileToggle) mobileToggle.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
    }
  }

  function closeDrawer() {
    if (drawer && backdrop) {
      drawer.classList.remove('is-open');
      backdrop.classList.remove('is-open');
      if (mobileToggle) mobileToggle.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
    }
  }

  if (mobileToggle) mobileToggle.addEventListener('click', openDrawer);
  if (closeBtn) closeBtn.addEventListener('click', closeDrawer);
  if (backdrop) backdrop.addEventListener('click', closeDrawer);

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && drawer && drawer.classList.contains('is-open')) {
      closeDrawer();
    }
  });

  /* 5. Reading Progress Indicator & Back to Top Visibility */
  var progressBar = document.getElementById('readingProgressBar');
  var backToTopBtn = document.getElementById('backToTopBtn');

  window.addEventListener('scroll', function() {
    var scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    var docHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
    if (progressBar && docHeight > 0) {
      var progress = (scrollTop / docHeight) * 100;
      var pVal = Math.round(Math.min(progress, 100));
      progressBar.style.width = pVal + '%';
      progressBar.setAttribute('aria-valuenow', pVal);
    }
    if (backToTopBtn) {
      if (scrollTop > 350) {
        backToTopBtn.classList.add('is-active');
      } else {
        backToTopBtn.classList.remove('is-active');
      }
    }
  }, { passive: true });

  if (backToTopBtn) {
    backToTopBtn.addEventListener('click', function() {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  /* 6. Copy Page URL with Toast Notification */
  var copyBtn = document.getElementById('copyPageUrlBtn');
  var toast = document.getElementById('toastMsg');

  function showToast(message) {
    if (!toast) return;
    toast.textContent = message;
    toast.classList.add('show');
    setTimeout(function() {
      toast.classList.remove('show');
    }, 3000);
  }

  if (copyBtn) {
    copyBtn.addEventListener('click', function() {
      var urlToCopy = copyBtn.getAttribute('data-url') || window.location.href;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(urlToCopy).then(function() {
          showToast('Link copied to clipboard!');
        }).catch(function() {
          showToast('Press Ctrl+C to copy URL');
        });
      } else {
        showToast('Press Ctrl+C to copy URL');
      }
    });
  }

  /* 7. Automatic Collapsible Table of Contents (TOC) */
  var articleBody = document.getElementById('articleBody');
  var tocBox = document.getElementById('autoTocBox');
  var tocList = document.getElementById('tocList');
  var tocToggle = document.getElementById('tocToggleBtn');
  var tocNav = document.getElementById('tocNavContainer');

  if (articleBody && tocBox && tocList) {
    var headings = articleBody.querySelectorAll('h2, h3');
    if (headings.length >= 2) {
      tocBox.style.display = 'block';
      headings.forEach(function(h, index) {
        if (!h.id) {
          h.id = 'heading-' + (index + 1);
        }
        var li = document.createElement('li');
        li.className = 'toc-item' + (h.tagName.toLowerCase() === 'h3' ? ' toc-sub' : '');
        var a = document.createElement('a');
        a.href = '#' + h.id;
        a.textContent = h.textContent;
        li.appendChild(a);
        tocList.appendChild(li);
      });

      if (tocToggle && tocNav) {
        tocToggle.addEventListener('click', function() {
          var isHidden = tocNav.style.display === 'none';
          tocNav.style.display = isHidden ? 'block' : 'none';
          tocToggle.textContent = isHidden ? '[Hide]' : '[Show]';
          tocToggle.setAttribute('aria-expanded', isHidden ? 'true' : 'false');
        });
      }
    }
  }

  /* 8. Responsive Table Wrappers for Mobile */
  if (articleBody) {
    var tables = articleBody.querySelectorAll('table');
    tables.forEach(function(table) {
      if (!table.parentElement.classList.contains('table-responsive-wrapper')) {
        var wrapper = document.createElement('div');
        wrapper.className = 'table-responsive-wrapper';
        table.parentNode.insertBefore(wrapper, table);
        wrapper.appendChild(table);
      }
    });
  }

  /* 9. Interactive MCQ Question Option Click & Answer Reveal */
  document.addEventListener('click', function(e) {
    // 9a. Handle student clicking an MCQ option (Instant Feedback)
    var opt = e.target.closest('.qa-option');
    if (opt) {
      var item = opt.closest('.qa-item');
      if (item) {
        var correctOpt = (item.getAttribute('data-correct') || '').toUpperCase().trim();
        var chosenOpt = (opt.getAttribute('data-opt') || '').toUpperCase().trim();
        var allOpts = item.querySelectorAll('.qa-option');

        allOpts.forEach(function(o) {
          o.classList.remove('opt-selected', 'opt-correct', 'opt-incorrect');
          var thisOpt = (o.getAttribute('data-opt') || '').toUpperCase().trim();
          if (correctOpt && thisOpt === correctOpt) {
            o.classList.add('opt-correct');
          }
        });

        if (chosenOpt && correctOpt) {
          if (chosenOpt === correctOpt) {
            opt.classList.add('opt-correct');
          } else {
            opt.classList.add('opt-incorrect');
          }
        } else {
          opt.classList.add('opt-selected');
        }

        // Auto-expand details or show .qa-answer
        var detailsBox = item.querySelector('details.qa-explanation-box');
        if (detailsBox) {
          detailsBox.open = true;
        } else {
          var ans = item.querySelector('.qa-answer');
          if (ans) {
            ans.classList.add('is-visible');
            ans.style.display = 'block';
          }
        }
      }
      return;
    }

    // 9b. Handle toggle button click
    var btn = e.target.closest('.qa-toggle-btn');
    if (btn) {
      // If it's a summary element, native browser <details> handles it automatically
      if (btn.tagName.toLowerCase() !== 'summary') {
        e.preventDefault();
        var item = btn.closest('.qa-item');
        if (item) {
          var ans = item.querySelector('.qa-answer');
          if (ans) {
            var isVisible = ans.classList.toggle('is-visible');
            if (ans.style.display === 'block') {
              ans.style.display = 'none';
              isVisible = false;
            } else if (ans.style.display === 'none') {
              ans.style.display = 'block';
              isVisible = true;
            } else {
              ans.style.display = isVisible ? 'block' : 'none';
            }
            btn.textContent = isVisible ? 'उत्तर लपवा (Hide Answer)' : '👉 उत्तर आणि सविस्तर स्पष्टीकरण पहा';
          }
        }
      }
    }
  });

  /* 11. Lazy Load Comments & reCAPTCHA */
  var commentEditor = document.getElementById('comment-editor');
  var commentFormWrap = document.getElementById('commentFormWrap');
  var loadCommentsBtn = document.getElementById('loadCommentsBtn');
  var commentLoadPrompt = document.getElementById('commentLoadPrompt');

  function initCommentEditor() {
    if (commentEditor && commentEditor.getAttribute('data-src')) {
      var realSrc = commentEditor.getAttribute('data-src');
      if (commentEditor.src !== realSrc) {
        commentEditor.src = realSrc;
      }
      if (commentLoadPrompt) commentLoadPrompt.style.display = 'none';
    }
  }

  if (loadCommentsBtn) {
    loadCommentsBtn.addEventListener('click', initCommentEditor);
  }

  if (commentFormWrap && 'IntersectionObserver' in window) {
    var commentObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          initCommentEditor();
          commentObserver.disconnect();
        }
      });
    }, { rootMargin: '300px 0px' });
    commentObserver.observe(commentFormWrap);
  }

  /* 10. Related Posts JSON Feed Fetcher */
  var relatedSection = document.getElementById('relatedPostsSection');
  var relatedGrid = document.getElementById('relatedPostsGrid');
  if (relatedSection && relatedGrid) {
    var label = relatedSection.getAttribute('data-label');
    var currentUrl = relatedSection.getAttribute('data-current-url');
    if (label) {
      var scriptUrl = '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json-in-script&callback=mpscRelatedCallback&max-results=5';
      window.mpscRelatedCallback = function(json) {
        var entries = (json && json.feed && json.feed.entry) ? json.feed.entry : [];
        var count = 0;
        relatedGrid.innerHTML = '';
        for (var i = 0; i < entries.length && count < 3; i++) {
          var entry = entries[i];
          var postUrl = '';
          for (var k = 0; k < entry.link.length; k++) {
            if (entry.link[k].rel === 'alternate') {
              postUrl = entry.link[k].href;
              break;
            }
          }
          if (postUrl === currentUrl) continue;
          var postTitle = entry.title.$t;
          var thumb = '';
          if (entry.media$thumbnail) {
            thumb = entry.media$thumbnail.url.replace('/s72-c/', '/w400-h225-c/');
          }
          var card = document.createElement('div');
          card.className = 'related-card';
          var thumbHtml = thumb ? '<div class="related-thumb-wrap"><img class="related-thumb" src="' + thumb + '" alt="' + postTitle.replace(/"/g, '&quot;') + '" loading="lazy"/></div>' : '';
          card.innerHTML = '<a href="' + postUrl + '">' + thumbHtml + '<div class="related-body"><h4 class="related-title">' + postTitle + '</h4></div></a>';
          relatedGrid.appendChild(card);
          count++;
        }
        if (count === 0) {
          relatedSection.style.display = 'none';
        }
      };
      var script = document.createElement('script');
      script.src = scriptUrl;
      document.body.appendChild(script);
    }
  }
});
//
